module fifo(clk, rst, wr_en, rd_en, din, dout, full, empty);
  input clk;
  input rst;
  input wr_en;
  input rd_en;
  input [7:0] din;
  output [7:0] dout;
  output full;
  output empty;

  reg [7:0] dout;
  reg [7:0] mem [0:15];
  reg [4:0] rd_ptr;
  reg [4:0] wr_ptr;

  wire write_fire;
  wire read_fire;

  assign empty = (wr_ptr == rd_ptr);
  assign full  = (wr_ptr[3:0] == rd_ptr[3:0]) && (wr_ptr[4] != rd_ptr[4]);

  assign write_fire = wr_en && !full;
  assign read_fire  = rd_en && !empty;

  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 5'b00000;
      rd_ptr <= 5'b00000;
      dout   <= 8'b00000000;
    end else begin
      if (write_fire) begin
        mem[wr_ptr[3:0]] <= din;
        wr_ptr <= wr_ptr + 5'b00001;
      end

      if (read_fire) begin
        dout <= mem[rd_ptr[3:0]];
        rd_ptr <= rd_ptr + 5'b00001;
      end
    end
  end
endmodule

